# binary shape source lower-left 6, big 6/4, zeros, and horizontal 7
src={(0,1),(1,0),(1,1),(2,1),(3,0),(3,1)}
big={(0,c) for c in range(5)}|{(1,c) for c in range(4)}|{(2,c) for c in range(5)}|{(3,c) for c in (0,2,3,4)}|{(4,4)}
zero={(0,c) for c in range(7)}|{(r,0) for r in range(1,7)} # 7x7 L
iso={(0,0)}
tri={(0,0),(0,1),(0,2)}
def transforms(s):
  out=[]
  for refl in (False,True):
    for rot in range(4):
      t=set()
      for r,c in s:
        if refl:c=-c
        for _ in range(rot):r,c=c,-r
        t.add((r,c))
      mr=min(r for r,c in t); mc=min(c for r,c in t)
      out.append({(r-mr,c-mc) for r,c in t})
  return out
def fits(s,h):
 for t in transforms(s):
  H=max(r for r,c in h)+1;W=max(c for r,c in h)+1
  for dr in range(H-max(r for r,c in t)):
   for dc in range(W-max(c for r,c in t)):
    if {(r+dr,c+dc) for r,c in t}<=h:return True
 return False
for nm,h in [('big6/4',big),('zeroL',zero)]:
 print('host',nm,'small6 fits?',fits(src,h),'7tri fits?',fits(tri,h),'iso fits?',fits(iso,h))
